const item = $input.first()?.json || {};
const senderId = item.sender_id || item.body?.message?.from?.id || item.body?.callback_query?.from?.id;
const chatId = item.chat_id || item.body?.message?.chat?.id || item.body?.callback_query?.message?.chat?.id;
const messageId = item.message_id || item.body?.callback_query?.message?.message_id;
const callbackQueryId = item.callback_query_id || item.body?.callback_query?.id;
const callbackData = item.callback_data || item.body?.callback_query?.data;
const textCommand = (item.command || item.body?.message?.text || '').trim();

let action = 'GET_STATUS';
let targetChatId = null;
let query = '';

if (callbackData) {
  if (callbackData === 'cmd_on') {
    action = 'ENABLE_GLOBAL';
    query = `UPDATE agent_control_state SET is_enabled = true, updated_by = ${senderId || 0}, updated_at = NOW() WHERE id = 1;`;
  } else if (callbackData === 'cmd_off') {
    action = 'DISABLE_GLOBAL';
    query = `UPDATE agent_control_state SET is_enabled = false, updated_by = ${senderId || 0}, updated_at = NOW() WHERE id = 1;`;
  } else if (callbackData === 'cmd_status') {
    action = 'GET_STATUS';
  } else if (callbackData === 'cmd_paused') {
    action = 'LIST_PAUSED';
  } else if (callbackData.startsWith('resume_')) {
    action = 'RESUME_CHAT';
    targetChatId = callbackData.replace('resume_', '').replace(/[^0-9-]/g, '');
    query = `UPDATE chat_conversation_state SET is_paused = false, pause_reason = 'Resumed by owner via panel', updated_at = NOW() WHERE chat_id = ${targetChatId};`;
  }
} else if (textCommand) {
  const parts = textCommand.split(/\s+/);
  const cmd = parts[0].toLowerCase();
  const argId = parts[1] ? parts[1].replace(/[^0-9-]/g, '') : null;

  if (cmd === '/on') {
    action = 'ENABLE_GLOBAL';
    query = `UPDATE agent_control_state SET is_enabled = true, updated_by = ${senderId || 0}, updated_at = NOW() WHERE id = 1;`;
  } else if (cmd === '/off') {
    action = 'DISABLE_GLOBAL';
    query = `UPDATE agent_control_state SET is_enabled = false, updated_by = ${senderId || 0}, updated_at = NOW() WHERE id = 1;`;
  } else if (cmd === '/pause' && argId) {
    action = 'PAUSE_CHAT';
    targetChatId = argId;
    query = `INSERT INTO chat_conversation_state (chat_id, is_paused, last_message_from, pause_reason, updated_at) VALUES (${targetChatId}, true, 'seller', 'Manual owner pause', NOW()) ON CONFLICT (chat_id) DO UPDATE SET is_paused = true, pause_reason = 'Manual owner pause', updated_at = NOW();`;
  } else if (cmd === '/resume' && argId) {
    action = 'RESUME_CHAT';
    targetChatId = argId;
    query = `INSERT INTO chat_conversation_state (chat_id, is_paused, last_message_from, pause_reason, updated_at) VALUES (${targetChatId}, false, 'seller', 'Resumed by owner', NOW()) ON CONFLICT (chat_id) DO UPDATE SET is_paused = false, pause_reason = 'Resumed by owner', updated_at = NOW();`;
  } else {
    action = 'GET_STATUS';
  }
}

// Query to execute update and fetch latest state
let fullSql = query ? `${query}\n` : '';
fullSql += `SELECT is_enabled, sleep_mode_enabled, updated_at FROM agent_control_state WHERE id = 1;\n`;
fullSql += `SELECT chat_id, pause_reason, updated_at FROM chat_conversation_state WHERE is_paused = true;`;

return {
  action,
  targetChatId,
  senderId,
  chatId,
  messageId,
  callbackQueryId,
  fullSql
};

const meta = $('Parse Owner Command & Action').first().json;
const stateRes = $('Execute Control Query').all().map(i => i.json);
const pausedRes = $('Fetch Paused Chats').all().map(i => i.json);

const agentState = stateRes[0] || { is_enabled: false };
const isEnabled = agentState.is_enabled;
const pausedChats = pausedRes.filter(p => p.chat_id);

let statusEmoji = isEnabled ? '🟢 ENABLED' : '🔴 DISABLED';
let text = `🤖 <b>AI Sales Agent — Owner Control Panel</b>\n\n`;
text += `• <b>Global Automation:</b> ${statusEmoji}\n`;
text += `• <b>Timezone:</b> Asia/Manila (PHT, UTC+8)\n`;
text += `• <b>Paused Chats / Human Takeover:</b> ${pausedChats.length > 0 ? `${pausedChats.length} active` : 'None'}\n`;

if (pausedChats.length > 0) {
  text += `\n<b>Paused Customer Chats:</b>\n`;
  for (const pc of pausedChats) {
    text += `  • <code>${pc.chat_id}</code> (${pc.pause_reason || 'Manual takeover'})\n`;
  }
}

text += `\n<i>Tap a button below or use backup commands (/on, /off, /status, /pause &lt;id&gt;, /resume &lt;id&gt;).</i>`;

// Construct Native Telegram Inline Keyboard Buttons
const keyboard = [
  [
    { text: '🟢 Turn ON', callback_data: 'cmd_on' },
    { text: '🔴 Turn OFF', callback_data: 'cmd_off' }
  ],
  [
    { text: '📊 Refresh Status', callback_data: 'cmd_status' },
    { text: '⏸️ Paused Chats', callback_data: 'cmd_paused' }
  ]
];

// Add one-click Resume buttons for any currently paused customer chats
for (const pc of pausedChats.slice(0, 5)) {
  keyboard.push([
    { text: `▶️ Resume Customer ${pc.chat_id}`, callback_data: `resume_${pc.chat_id}` }
  ]);
}

return {
  chat_id: meta.chatId,
  message_id: meta.messageId,
  callback_query_id: meta.callbackQueryId,
  action: meta.action,
  reply_text: text,
  reply_markup: { inline_keyboard: keyboard },
  is_enabled: isEnabled,
  paused_count: pausedChats.length
};

